package com.library.model.entity;
import java.time.LocalDateTime;
public class BorrowRecord extends BaseEntity { private Long readerId,bookId,operatorId; private LocalDateTime borrowTime,dueTime,returnTime; private Integer status; private String remark;
 public Long getReaderId(){return readerId;} public void setReaderId(Long v){readerId=v;} public Long getBookId(){return bookId;} public void setBookId(Long v){bookId=v;} public Long getOperatorId(){return operatorId;} public void setOperatorId(Long v){operatorId=v;} public LocalDateTime getBorrowTime(){return borrowTime;} public void setBorrowTime(LocalDateTime v){borrowTime=v;} public LocalDateTime getDueTime(){return dueTime;} public void setDueTime(LocalDateTime v){dueTime=v;} public LocalDateTime getReturnTime(){return returnTime;} public void setReturnTime(LocalDateTime v){returnTime=v;} public Integer getStatus(){return status;} public void setStatus(Integer v){status=v;} public String getRemark(){return remark;} public void setRemark(String v){remark=v;} }
